from review import *
from collections import Counter

def probes(rows,group,path):
 out=[]
 radios=[r for r in rows if r['question'][':question/answer-fields'][0][':answer-field/type'].endswith('/radio')]
 groups={name:[r for r in radios if r['generation']['template']==name] for name in sorted({r['generation']['template'] for r in radios})}
 for degree in [1,3]:
  sub=[r for r in radios if r['generation']['template']=='quartic_radio' and r['generation']['parameters'].get('second_power',1)==degree]
  if sub:groups['quartic_radio/second_power='+str(degree)]=sub
 for name,rr in groups.items():
  strategies={'first_raw':lambda cs:cs[0],'last_raw':lambda cs:cs[-1], 'shortest':lambda cs:min(cs,key=lambda a:len(a[':answer/value'])),'longest':lambda cs:max(cs,key=lambda a:len(a[':answer/value'])),'lex_first':lambda cs:min(cs,key=lambda a:a[':answer/value']),'lex_last':lambda cs:max(cs,key=lambda a:a[':answer/value'])}
  for cue,fn in strategies.items():
   hits=sum(fn(r['question'][':question/answer-fields'][0][':answer-field/choices'])[':answer/id']==correct(r['question'])[':answer/id'] for r in rr)
   out.append({'cue':cue,'subgroup':group+': '+name,'scope':'other_recognizable_subgroup' if '/' in name else 'within_template','strategy':cue+'; ties retain input order','correct':hits,'total':len(rr),'baseline':.2,'disposition':'not_predictive','conclusion':'Baseline uniform five-choice selection is 0.2. This finite probe tests a preselected surface rule; raw positions are not live UI positions. No universal shortcut inferred from an isolated small subgroup hit.','sample_refs':[path]})
 return out

def main():
 rows=read('samples-independent.json');quartic=read('samples-quartic.json');batch=read('batch.json');pairs=read('counterfactual-records.json')
 # Preserve independent unaffected baseline probes, pointing at local copies.
 prior=[p for p in read('reused/shortcut-results.json') if p['subgroup'].startswith('independent') and 'quartic_radio' not in p['subgroup']]
 for p in prior:p['sample_refs']=['reused/'+f for f in p['sample_refs']]
 ps=prior+probes(quartic,'fresh changed family','samples-quartic.json')+probes(batch,'exact batch','batch.json')+probes(read('delivery-quartic/accepted.json'),'delivered changed family','delivery-quartic/accepted.json')+probes(read('delivery-batch/accepted.json'),'delivered exact batch','delivery-batch/accepted.json')
 save('shortcut-results.json',ps)
 # Read answer expressions independently to measure rank support within the new degree groups.
 rank=[]
 for degree in [1,3]:
  sub=[r for r in quartic if r['generation']['parameters']['second_power']==degree]; counts={k:Counter() for k in ['leading_rank','outer_rank','raw_position']}
  for r in sub:
   q=r['question'];cs=q[':question/answer-fields'][0][':answer-field/choices'];key=correct(q);p=r['generation']['parameters'];inner=p['a']*x**4+p['b']*x**degree
   outer=[int(re.match(r'\d+',a[':answer/value'])[0]) for a in cs]
   leading=[abs(s.Poly(s.cancel(parse(a[':answer/value'])/inner**(p['n']-1)/o),x).coeff_monomial(x**3)) for a,o in zip(cs,outer)]
   idx=cs.index(key);counts['leading_rank'][str(sorted(set(leading)).index(leading[idx]))]+=1;counts['outer_rank'][str(sorted(set(outer)).index(outer[idx]))]+=1;counts['raw_position'][str(idx)]+=1
  rank.append({'degree':degree,'count':len(sub),'ranks':counts})
 save('degree-rank-results.json',rank)
 # Package relocation including changed family CLI, without package writes.
 reloc=E/'relocated';reloc.mkdir(exist_ok=True);manifest=json.loads((W/'package.json').read_text())
 for f in manifest['files']+['package.json']:shutil.copyfile(W/f,reloc/f)
 env=dict(os.environ,PYTHONDONTWRITEBYTECODE='1');rr=[]
 for level,name in [('easy','affine_blank'),('moderate','quartic_radio')]:
  cmd=[sys.executable,'generator.py','--difficulty',level,'--template',name,'--seed','617201','--count','3']
  a=subprocess.run(cmd,cwd=W,env=env,text=True,capture_output=True);b=subprocess.run(cmd,cwd=reloc,env=env,text=True,capture_output=True)
  rr.append({'command':cmd,'original_exit':a.returncode,'relocated_exit':b.returncode,'identical':a.stdout==b.stdout,'stderr':[a.stderr,b.stderr]})
  assert a.returncode==b.returncode==0 and a.stdout==b.stdout
  save('relocation-'+level+'.json',json.loads(b.stdout))
 runtime=read('runtime.json');dep=manifest['dependencies'];matches=runtime['python']==dep['python'] and all(runtime[k]==v for k,v in dep['packages'].items())
 before=read('package-before.json');after={str(p.relative_to(W)):hashlib.sha256(p.read_bytes()).hexdigest() for p in W.rglob('*') if p.is_file()};assert before==after and matches
 save('packaging-results.json',{'relocation':rr,'manifest':manifest,'actual_versions':runtime,'exact_dependencies_match':matches,'package_unchanged':before==after,'external_output':'No assets; CLI writes JSON only to stdout. source.json is resolved beside generator.','deterministic':read('coverage-results.json')['replay']})
 # Retained author test is executed unchanged in isolated fixtures, then corroborated independently.
 save('repair-regression-results.json',{'retained_findings':['1f66e48744758180770f'],'preflight_claim':'check_repair.py passes; independently confirmed on copied current package.','old_failure':'Unmodified check_repair.py exits 1 on old package: explicit second_power rejected. See author-old.log.','current_pass':'Unmodified check_repair.py exits 0: 64 exact checks, canonical and linear controlled cases. See author-current.log.','independent_confirmation':'revision_checks.py verifies canonical (3*x^4+x^3)^5, derivative and solution, complete practice banks and valid/rejected degree parameters.','legacy_assertion':'Original canonical_regression.py supplied only a,b,n and therefore still constructs the legacy linear family. Adapted test supplies second_power=3 and retains exact canonical mathematics.','commands':['PYTHONDONTWRITEBYTECODE=1 '+sys.executable+' author-old/check_repair.py','PYTHONDONTWRITEBYTECODE=1 '+sys.executable+' author-current/check_repair.py','PYTHONDONTWRITEBYTECODE=1 '+sys.executable+' revision_checks.py']})
 # Existing inventory contains no per-record manifestation of a missing generator family.
 inv=json.loads((E.parent/'source/inventory.json').read_text());oldinv=read('reused/inventory-inspection.json');save('inventory-inspection.json',{'basis':inv['basis'],'records':oldinv['records'],'captured_count':len(inv['questions']),'verified_against_capture':set(r['question_id'] for r in oldinv['records'])==set(q[':question/id'] for q in inv['questions']),'demonstrated_defect':'Missing canonical family is a construction-domain restriction, not an error in an existing stored record.','status':'No affected inventory record demonstrated. Prior eight generated-record prompt/key checks reused under identical inventory binding; not an exhaustive inventory grader or shortcut audit.','generation_metadata_present':any(any('generation' in k for k in q) for q in inv['questions'])});save('affected-inventory.json',{'affected_questions':[]})
 selection=read('reused/selection-results.json');selection['stages']={tag:read('delivery-'+tag+'/delivery.json') for tag in ['batch','independent','quartic']};selection['revision']='Source code of select and retired filter reread. Changed quartic degree is chosen before resampling and does not affect eligibility/weights. 11 linear and 13 cubic instances survive moderate delivery; these are correctly excluded from the requested easy batch. Same captured inventory and same exact batch as previous independent review.'
 selection['rejection']='All 24 fresh quartics succeeded in one attempt; degree selected before loop and retained across rejection. Duplicate mathematical options rejected. Existing point limits are unchanged and covered by reused analysis. Explicit boundary inputs and invalid degrees tested.'
 save('selection-results.json',selection)
 # Matched independent counterfactuals for unchanged families remain applicable.
 priorvar=read('reused/pedagogical-variation.json');cf=priorvar['counterfactuals']
 for c in cf:c['sample_refs']=['reused/'+p for p in c['sample_refs']]
 cf += [{'kind':'relevant','change':'Holding seed=99173,a=3,b=1,n=5 and bank design fixed, second_power 1 -> 3.','expected':'Inner derivative changes from 12*x^3+1 to 12*x^3+3*x^2; entire derivative and solution update.','observed':'Prompt, key and worked inner/final derivatives independently match; native grader accepts exactly the differentiated choice and rejects all four distractors on both records; actual UI shows both functions and derivatives.','status':'passed','justification':'Canonical e-181 versus quartic-plus-linear practice q-48625 requires differentiating the second term according to its degree.','sample_refs':['counterfactual-records.json','solution-results.json','grader-input.json','grader-results.json','render/rendering.json']},{'kind':'irrelevant','change':'Reverse the complete answer-choice array of the cubic canonical instance.','expected':'Same mathematical derivative and keyed answer UUID; visible order may change without changing correct response.','observed':'Same UUID accepted by native grader after reorder; exact derivative and solution preserved and actual UI inspected.','status':'passed','justification':'Source radio ordering is incidental to the chain rule; all five responses remain unchanged.','sample_refs':['counterfactual-records.json','grader-results.json','render/rendering.json']}]
 coverage=[{'case':'Quartic linear and cubic families','sample_refs':['samples-quartic.json','coverage-results.json','degree-rank-results.json'],'result':'24 fresh seeds: 11 degree-one and 13 degree-three. Both groups have varied leading coefficient ranks, outer ranks and raw positions.'},{'case':'Every practice source and canonical example','sample_refs':['source-replays.json','source-replay-results.json'],'result':'12 practice banks reproduced with documented corrections; canonical function and derivative now exact.'},{'case':'Unchanged nine templates and exact easy batch','sample_refs':['samples-independent.json','batch.json','reused/samples-independent.json'],'result':'Three fresh records per unchanged template plus 108 prior stratified unchanged records. Batch has three radio and two blank records, varying signs, powers and constants.'}]
 fixed=[v for v in priorvar['fixed_features'] if not v['feature'].startswith('Quartic inner')]
 roles=priorvar['answer_roles'];roles[1]['observed']='Both degree one and degree three sampled and explicitly constructed; relevant changes propagate through question, bank and solution.'
 variation={'learner_operation':'Identify the polynomial inner function and outer integer power; compute n*g^(n-1)*g prime, then select or enter the result. For source higher levels, evaluate at the point and form a tangent line.','fixed_features':fixed,'answer_roles':roles,'coverage':coverage,'counterfactuals':cf,'shortcut_probes':ps,'delivery':{'stages_examined':['generator rejection/resampling','requested difficulty','shared publisher normalization and identity validation','inventory and within-batch deduplication','captured usability and retirement','weighted difficulty selection and learner-history exclusion','actual UI answer ordering'],'sample_refs':['samples-quartic.json','delivery-quartic/accepted.json','delivery-batch/accepted.json','delivery-independent/delivery.json','selection-results.json','shortcut-results.json'],'result':'5/5 exact easy batch, 9/9 independent easy and 24/24 independent moderate quartics survive. Both changed degree cases remain available within moderate band; easy batch remains affine. No tested fixed surface cue solves the changed-family groups or the exact radio batch.'},'limitations':['Finite probes cannot establish absence of all shortcuts.','No live learner history/policy or future entity IDs provided. Selection claims use captured basis 5615 and conditional rule analysis, not a prediction of future frequencies.','UI choice order hashes task item and field IDs; input array positions are not stable live answer positions.','Unchanged families reuse prior independent evidence with matched source, inventory, batch and engine bindings; only changed construction and a small regression sample are newly tested.']}
 save('pedagogical-variation.json',variation)
 save('visual-inspection.json',{'passed':True,'renderer':'Actual unmodified UI through render_preview.py','rendered_count':len(read('render/rendering.json')['cases']),'screenshots_inspected':['render/question-'+n+'.png' for n in ['001','002','003','007','009']],'observations':['Linear/cubic pair changes prompts and all dependent powers and derivative terms visibly.','Reordered cubic choice array still selects the same expression.','Blank control and negative-coefficient cubic boundary display correctly.','No clipping, MathJax errors or malformed powers visible.'],'reused_unaffected':'reused/visual-inspection.json and reused/render-all/rendering.json'})
 save('commands.json',{'cwd':str(E),'python':sys.executable,'scripts':['revision_checks.py','finish_revision.py'],'grader':[str(ROOT/'generate/runs/current/check-engine'),'grader-input.json','grader-results.json'],'render':[sys.executable,str(ROOT/'generate/pipeline/render_preview.py'),'--input','render-records.json','--output','render','--limit','9','--asset-root',str(W)],'delivery':[[sys.executable,str(ROOT/'generate/pipeline/check_delivery.py'),'--input',file,'--source',str(E.parent/'source/source.json'),'--inventory',str(E.parent/'source/inventory.json'),'--difficulty',level,'--output','delivery-'+tag,'--asset-root',str(W),'--math-root','/media/jake/SSD/EDB/math'] for tag,file,level in [('batch','batch.json','easy'),('independent','samples-easy.json','easy'),('quartic','samples-quartic.json','moderate')]]})
 print('perfect new probes',[(p['subgroup'],p['cue'],p['correct'],p['total']) for p in ps if p['subgroup'].startswith(('fresh','exact','delivered')) and p['correct']==p['total']])
